code='''def transform(grid):
    n=len(grid); h=next((i for i,row in enumerate(grid) if all(x==8 for x in row)), None)
    w=next((j for j,x in enumerate(grid[0]) if all(row[j]==8 for row in grid)), None)
    bh=h; bw=w
    nr=(n+1)//(bh+1); nc=(len(grid[0])+1)//(bw+1)
    marks={}
    for r in range(nr):
        for c in range(nc):
            vals=set()
            for i in range(r*(bh+1),r*(bh+1)+bh):
                for j in range(c*(bw+1),c*(bw+1)+bw):
                    if grid[i][j] not in (0,8): vals.add(grid[i][j])
            if vals: marks.setdefault(next(iter(vals)),[]).append((r,c))
    paint={}
    for color,pts in marks.items():
        for r,c in pts: paint[(r,c)]=color
        for a,(r1,c1) in enumerate(pts):
            for r2,c2 in pts[a+1:]:
                if r1==r2:
                    for c in range(min(c1,c2),max(c1,c2)+1): paint.setdefault((r1,c),color)
                if c1==c2:
                    for r in range(min(r1,r2),max(r1,r2)+1): paint.setdefault((r,c1),color)
    # crossings of distinct colored paths are 6
    for r,c in list(paint):
        colors=set()
        for color,pts in marks.items():
            if any((r==a and min(b,d)<=c<=max(b,d)) or (c==b and min(a,e)<=r<=max(a,e)) for (a,b) in pts for (e,d) in pts): colors.add(color)
        if len(colors)>1: paint[(r,c)]=6
    out=[row[:] for row in grid]
    for (r,c),color in paint.items():
        for i in range(r*(bh+1),r*(bh+1)+bh):
            for j in range(c*(bw+1),c*(bw+1)+bw): out[i][j]=color
    return out
'''
